    (1801405, ''2026IP81405'', N''IP CADUCITE EPSILON'', ''IP'', 0), (1801406, ''2026IP81406'', N''IP CERTIFICAT A VENIR'', ''IP'', 0),
    (1801407, ''2026IP81407'', N''IP CERTIFICAT ZETA'', ''IP'', 0), (1801408, ''2026IP81408'', N''IP EUROPEENNE'', ''IP'', 1),
