-- Le reglage de RIG_DEV : la non avenue sans enrolement d'OP cree IPCNAV (IP_NONAVENUE_EVT_SI_PAS_ENROLER_OP) ; la caducite n'a pas
-- de reglage (NULL dans RIG_DEV) : elle enrole une OP IPCADSO.
IF NOT EXISTS (SELECT 1 FROM soc.Reglage WHERE Code = 'IP_NONAVENUE_EVT_SI_PAS_ENROLER_OP')
    INSERT INTO soc.Reglage (Code, Libelle, Valeur) VALUES ('IP_NONAVENUE_EVT_SI_PAS_ENROLER_OP', 'Non avenue sans OP (banc lot 8)', 'IPCNAV');

EXEC sp_executesql N'
-- Les codes d''evenement de RIG_DEV (CODE_EVE_PRO, R_CODEEVEPRO_CODE_EVE_PRO_EXPIRE lu le 27/11/2026) : IOIP expire en IPEXECUT,
-- ISIGNI en IPNAV, ICONSOIP et IPCONSOPOS en IPCAD ; IPOPOS et IPSIGNIF n''ont pas de code « expire ».
INSERT INTO v2.CODE_EVE_PRO (R_CODEEVEPRO_VALEUR, R_CODEEVEPRO_LIBELLE_ECRAN, R_CODEEVEPRO_TYPE_EVE_PRO, R_CODEEVEPRO_CODE_EVE_PRO_EXPIRE)
SELECT v.c, v.l, ''I'', v.e FROM (VALUES
    (''IOIP'', ''Opposition attendue'', ''IPEXECUT''), (''IPOPOS'', ''Opposition attendue (2022)'', NULL),
    (''ISIGNI'', ''Signification attendue'', ''IPNAV''), (''IPSIGNIF'', ''Signification (2022)'', NULL),
    (''ICONSOIP'', ''Consignation attendue'', ''IPCAD''), (''IPCONSOPOS'', ''Consignation (2022)'', ''IPCAD''),
    (''IPCERTNOPP'', ''Certificat de non-opposition'', NULL), (''IPEXECUT'', ''Executoire'', NULL), (''IPEXECUTLR'', ''Executoire LRAR'', NULL),
    (''IPEXECUTR'', ''Executoire LR'', NULL), (''IPNAV'', ''Non avenue'', NULL), (''IPCAD'', ''Caducite'', NULL),
    (''IPCNAV'', ''Non avenue sans OP'', NULL), (''IPCNAVLR'', ''Non avenue sans OP LRAR'', NULL), (''IPCNAVR'', ''Non avenue sans OP LR'', NULL),
    (''IPDESIN'', ''Desistement'', NULL)) AS v (c, l, e)
WHERE NOT EXISTS (SELECT 1 FROM v2.CODE_EVE_PRO AS x WHERE x.R_CODEEVEPRO_VALEUR = v.c);
