    R_CODEAFFAIR_TYPE_DECISION) VALUES
    (''IPCADSO'', ''Opposition caducite'', ''JROP'', ''RP'', 1, ''0A'', NULL, ''SO'', ''OPCAD'', ''IPCAD''),
    (''IPNAVSO'', ''Opposition non avenue'', ''JROP'', ''RP'', 1, ''0A'', ''OPPIECES'', ''SO'', ''OPNAV'', ''IPNAV'');
