-- Les numeros source des echeances (EVNPR_NUMERO_SOURCE) : l''evenement survenu cree depuis un expire les porte en EP_LIE.
UPDATE v2.EVENEMENT_PROCEDURE SET EVNPR_NUMERO_SOURCE = ''SRC-'' + CAST(EVNPR_ID_EVNPR AS varchar(10)) WHERE EVNPR_ID_EVNPR BETWEEN 1801471 AND 1801481;
',
    N'@aujourdhui datetime', @aujourdhui;

-- LES EDITIONS DES EVENEMENTS (EditionsEvenement.cs, lot 8, 27/11/2026 ; controle final : OPE_TRAITEMENTS.cs:822-835 les cree).
-- Les maquettes CEP_EDITION de RIG_DEV (lues le 27/11/2026) : IPEXECUTLR -> IP_ENVOI_EXECUT, destinataire « AVD,LRAR » (l'avocat
-- du demandeur, sinon le demandeur, en LRAR) ; ses parametres d'edition et celui de l'imprime JLRAR, a la liste de RIG_DEV.
-- Trois maquettes du banc de plus, chacune pour une regle : une condition que la V3 n'evalue pas (« +TF701 », tranches de salaries
-- d'une PC : nommee, rien n'est cree) ; une maquette de type « M » (mesure : jamais pour une instance) ; IPCAD -> une note « DI »
-- (le document interne) ; et IPCERTNOPP -> un parametre SANS liste (GetAllEditions n'edite rien). Les parties de 1801401 recoivent
-- un numero source (PART_D / PART_AV.. : RecupDestEditLot2FROMInstance ne prend qu'une partie qui en a un).
IF COL_LENGTH('v2.CEP_EDITION', 'CEPED_CONDITION') IS NULL ALTER TABLE v2.CEP_EDITION ADD CEPED_CONDITION varchar(max) NULL;
IF COL_LENGTH('v2.CEP_EDITION', 'CEPED_AUTRE_PARAMETRE') IS NULL ALTER TABLE v2.CEP_EDITION ADD CEPED_AUTRE_PARAMETRE varchar(max) NULL;
IF COL_LENGTH('v2.PARTIE', 'PRT_NUMERO_SOURCE') IS NULL ALTER TABLE v2.PARTIE ADD PRT_NUMERO_SOURCE varchar(40) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_CODE_ENTITE_DESTINATAIRE') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_CODE_ENTITE_DESTINATAIRE varchar(16) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_VALEUR_ID_DESTINATAIRE') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_VALEUR_ID_DESTINATAIRE varchar(40) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_TYPE_DESTINATAIRE') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_TYPE_DESTINATAIRE varchar(10) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_LIBELLE_SOURCE') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_LIBELLE_SOURCE varchar(255) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_PARAMETRE_GENERATION') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_PARAMETRE_GENERATION varchar(max) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_CODE_MAQUETTE') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_CODE_MAQUETTE varchar(40) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_LES_NUMEROS') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_LES_NUMEROS varchar(128) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_TYPE_DOCUMENT') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_TYPE_DOCUMENT varchar(10) NULL;
EXEC sp_executesql N'
UPDATE v2.PARTIE SET PRT_NUMERO_SOURCE = ''PRT-'' + CAST(PRT_ID_PRT AS varchar(10)) WHERE PRT_ID_PRT IN (1801461, 1801462);
