    (''JLRAR'', N''Imprimé LRAR La Poste'', ''FUSION_RIG'', N''<PARAMETRES NUMLRAR="" CODE_PROCESSUS="EDIT_LRAR" CODE_ENTITE_SOURCE="EVT_PROC" CODE_MAQUETTE="3801_JLRAR" TYPE_PAPIER="LRAR" LOT="LRAR_USER" AGRAFAGE="0" RECTO_VERSO="0" TYPE_GENERATION="FUSION_RIG" NOMBRE_EXEMPLAIRES="1" IMPRESSION="1" AFFICHER_AVANT_IMPRESSION="0" LIBELLE_DOCUMENT="Imprimé LRAR La Poste" READ_ONLY="0" NE_PAS_GENERER="0" GROUPAGE_AUTOMATIQUE="0" NON_SUPPRESSIBLE="0" />''),
